package org.asciidoc.intellij.psi;

import com.intellij.testFramework.fixtures.BasePlatformTestCase;
import org.asciidoc.intellij.inspections.AsciiDocLinkResolveInspection;

import java.util.List;

/**
 * Auto-generated section IDs can be switched off with <code>:!sectids:</code>.
 */
public class AsciiDocSectionIdsTest extends BasePlatformTestCase {

  public void testCompletionOffersIdsByDefault() {
    myFixture.configureByText("a.adoc", "== Headline\n\n<<<caret>>\n");
    myFixture.completeBasic();
    List<String> strings = myFixture.getLookupElementStrings();
    assertNotNull(strings);
    assertContainsElements(strings, "_headline");
  }

  public void testCompletionOmitsIdsOfSectionsAfterUnset() {
    myFixture.configureByText("a.adoc", "== Before\n\n:!sectids:\n\n== After\n\n[#explicit]\n== With ID\n\n:sectids:\n\n== Again\n\n<<<caret>>\n");
    myFixture.completeBasic();
    List<String> strings = myFixture.getLookupElementStrings();
    assertNotNull(strings);
    assertContainsElements(strings, "_before", "explicit", "_again");
    assertDoesntContain(strings, "_after");
    // natural cross references work without generated IDs
    assertContainsElements(strings, "After");
  }

  public void testCompletionOmitsIdsWithAlternativeUnsetSyntax() {
    myFixture.configureByText("a.adoc", ":sectids!:\n\n== After\n\n<<<caret>>\n");
    myFixture.completeBasic();
    List<String> strings = myFixture.getLookupElementStrings();
    assertNotNull(strings);
    assertDoesntContain(strings, "_after");
  }

  public void testCompletionOmitsIdsWhenUnsetInAsciidoctorconfig() {
    myFixture.addFileToProject(".asciidoctorconfig", ":!sectids:\n");
    myFixture.configureByText("a.adoc", "== After\n\n<<<caret>>\n");
    myFixture.completeBasic();
    List<String> strings = myFixture.getLookupElementStrings();
    assertNotNull(strings);
    assertDoesntContain(strings, "_after");
  }

  public void testFileSettingOverridesAsciidoctorconfig() {
    myFixture.addFileToProject(".asciidoctorconfig", ":!sectids:\n");
    myFixture.configureByText("a.adoc", ":sectids:\n\n== After\n\n<<<caret>>\n");
    myFixture.completeBasic();
    List<String> strings = myFixture.getLookupElementStrings();
    assertNotNull(strings);
    assertContainsElements(strings, "_after");
  }

  public void testCompletionOmitsIdsWhenUnsetInAntoraYml() {
    myFixture.addFileToProject("antora.yml", "name: test\nversion: '1.0'\nasciidoc:\n  attributes:\n    sectids: false\n");
    myFixture.addFileToProject("modules/ROOT/pages/index.adoc", "");
    myFixture.configureFromExistingVirtualFile(
      myFixture.addFileToProject("modules/ROOT/pages/a.adoc", "[#explicit]\n== With ID\n\n== After\n\n<<<caret>>\n").getVirtualFile());
    myFixture.completeBasic();
    List<String> strings = myFixture.getLookupElementStrings();
    assertNotNull(strings);
    assertDoesntContain(strings, "_after");
  }

  public void testValidationReportsAutogeneratedIdOnlyWhereEnabled() {
    myFixture.enableInspections(AsciiDocLinkResolveInspection.class);
    myFixture.configureByText("a.adoc",
      "== Before\n\n<<_before>>\n\n:!sectids:\n\n== After\n\n<<<error descr=\"Anchor doesn't resolve\">_after</error>>>\n\n:sectids:\n\n== Again\n\n<<_again>>\n");
    myFixture.checkHighlighting();
  }
}
